import{_ as t,c as a,o,ae as n}from"./chunks/framework.Bi6zybwU.js";const b=JSON.parse('{"title":"Tools and Settings","description":"Tools and Settings","frontmatter":{"title":"Tools and Settings","description":"Tools and Settings"},"headers":[],"relativePath":"guide/table-management/tools-and-settings.md","filePath":"guide/table-management/tools-and-settings.md"}'),s={name:"guide/table-management/tools-and-settings.md"};function l(r,e,i,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="tools-and-settings" tabindex="-1">Tools and Settings <a class="header-anchor" href="#tools-and-settings" aria-label="Permalink to &quot;Tools and Settings&quot;">​</a></h1><p>From the admin dashboard (left sidebar), go to the **Tools **option from the Ninja Tables plugin. You&#39;ll see the &quot;Tools and Settings&quot; tab where you can customize the table&#39;s global appearance, permissions, etc. <img src="https://ninjatables.com/wp-content/uploads/2022/11/tools-settings-01-scaled.webp" alt="Tools &amp; Settings"></p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p>Ninja Tables can import tables from existing data, like from a CSV or JSON file. You can also import existing tables from the other WordPress table plugins. Check the **<a href="https://ninjatables.com/docs-category/import-export/" target="_blank" rel="noreferrer">link </a>**to learn more about how to <strong>Import</strong>.</p><h2 id="global-appearance" tabindex="-1">Global Appearance <a class="header-anchor" href="#global-appearance" aria-label="Permalink to &quot;Global Appearance&quot;">​</a></h2><p>The newly generated tables will use the following settings. You may, of course, adjust the appearance settings for each level of the table.</p><ul><li>The first feature is the** Default Styling Library**, which manages the library you must work with. Three different libraries are available in this segment, such as <strong>Semantic UI</strong>, <strong>Bootstrap 4</strong> &amp; <strong>Bootstrap 3</strong>. Each of these libraries has various components once you select one of them.</li><li>The second feature is the** Default Table** <strong>Styles</strong> option which offers several functions like <strong>Single Line Cells</strong>, <strong>Fixed Layout</strong>, <strong>Hover Rows</strong>, <strong>Bordered Table,</strong> and many more. Check these options according to your styling needs. Hover rows, Striped rows, and Vertically centered table cell contents are all checked at the beginning of the newly constructed table. <img src="https://ninjatables.com/wp-content/uploads/2022/11/Global-Apperrance-02-scaled.webp" alt="Global Appearance"></li><li>The other function is the** Default Features** which defines many components, all you have to do is check the one you need for setting your table. Enable the visitor to filter or search the table and enable sorting of the table by the visitor; these two default features are checked at the beginning.</li><li>You can style your table in 13 different pre-defined color schemes. By default, there will be a default table color at the beginning. Other than predefined colors, Ninja Tables has custom <a href="https://ninjatables.com/docs/table-color-settings/" target="_blank" rel="noreferrer">table color</a> options in the &quot;Table Design&quot; tab.</li><li>In Default Pagination Setting, you can select how many items you want to show per page. You can also disable pagination here.</li><li>Default Font Setting feature allows users to change the Table’s <strong>Font Family</strong> &amp; **Font Size **according to their requirements.</li><li>Click on the **Update **button when you are done!</li></ul><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p>By default, Only the Administrator has access to manage the tables. By selecting additional roles below, You can give access to manage your Tables to other user roles. <img src="https://ninjatables.com/wp-content/uploads/2022/11/Permission-03-scaled.webp" alt="Permission"></p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>For the licensing option to appear in your tools and settings, you must install Ninja Table Pro. From the left sidebar, click on the **License **option &amp; activate your <strong>Ninja Table Pro</strong> by providing the license key below. 📌 See <a href="https://ninjatables.com/docs/how-to-install-and-activate-ninja-tables-plugin/" target="_blank" rel="noreferrer">How to install and activate Ninja Tables</a> from here. <img src="https://ninjatables.com/wp-content/uploads/2022/11/License-04-scaled.webp" alt="License"></p><h2 id="global-settings" tabindex="-1">Global Settings <a class="header-anchor" href="#global-settings" aria-label="Permalink to &quot;Global Settings&quot;">​</a></h2><p>From here, you can clear the table cache or handle Javascript errors.</p><h3 id="clear-table-cache" tabindex="-1"><strong>Clear Table Cache</strong> <a class="header-anchor" href="#clear-table-cache" aria-label="Permalink to &quot;**Clear Table Cache**&quot;">​</a></h3><p>If you want to clear all the** Ninja Tables cache**, click on the **Clear Table Cache <strong>button. <img src="https://ninjatables.com/wp-content/uploads/2022/11/Global-Settings-05-scaled.webp" alt="Clear Table Cache"> This is all about</strong> **the <strong>Tools and settings</strong> of Ninja Tables.</p>',15)])])}const p=t(s,[["render",l]]);export{b as __pageData,p as default};
